    "declic_frequence": "nādā (appeler, invoquer, racine ن-د-ي) ouvre la sourate au v.3 sur une image d'intimité rare : idh nādā rabbahu nidāʾan khafiyyan — Zacharie « appela son Seigneur d'un appel discret ». Le nidāʾ khafī, l'invocation chuchotée, secrète, enseigne l'adab de la prière : l'imploration la plus vraie n'est pas la plus bruyante mais la plus intime. Dieu entend le murmure du cœur ; nul besoin d'élever la voix pour être exaucé. C'est dans ce secret que naît le miracle."
